import java.util.AbstractSet;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.ConcurrentModificationException;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Objects;
import java.util.Optional;
import java.util.Random;
import java.util.SortedSet;
import java.util.TreeSet;

/**
 * A self-balancing AVL binary search tree that implements {@link SortedSet}.
 *
 * <p>Rather than allocating a node object per element, the tree is flattened
 * into a <em>structure of parallel arrays</em> indexed by an integer node id:
 * {@code value[i]} holds the element, {@code left[i]}/{@code right[i]} hold child
 * ids (or {@link #NIL} for none), and {@code balance[i]} holds the AVL balance
 * factor {@code height(left) - height(right)} in a single byte. This eliminates
 * the per-node object header and reference indirection of a linked structure and
 * keeps the hot fields contiguous in memory, which is friendlier to the CPU
 * cache. Slots freed by deletion are recycled through a free list, and the
 * arrays grow on demand.
 *
 * <p>Balancing keeps the height in O(log n), guaranteeing O(log n) {@link #add},
 * {@link #remove} and {@link #contains}. Elements are ordered by their natural
 * ordering ({@link Comparable}) or by a {@link Comparator} supplied at
 * construction, and iteration yields them in ascending order. Balance factors
 * are maintained incrementally; node heights are derived on demand only by
 * {@link #height()} and {@link #validate()}.
 *
 * <p>As a {@code SortedSet}, duplicates and {@code null} elements are rejected,
 * and {@link #subSet}/{@link #headSet}/{@link #tailSet} return live, backed
 * range views. Iterators are fail-fast and support {@link Iterator#remove()}.
 *
 * @param <T> the type of elements held in the tree
 */
class AVLTree<T> extends AbstractSet<T> implements SortedSet<T> {

    /** Sentinel node id meaning "no node" (the array analogue of {@code null}). */
    private static final int NIL = -1;

    private static final int INITIAL_CAPACITY = 16;

    // Structure-of-arrays node storage, indexed by node id.
    private Object[] value = new Object[INITIAL_CAPACITY];
    private int[] left = new int[INITIAL_CAPACITY];
    private int[] right = new int[INITIAL_CAPACITY];
    private byte[] balance = new byte[INITIAL_CAPACITY];

    private final Comparator<? super T> comparator;
    private int root = NIL;
    private int size;
    private int highWater;   // first never-yet-allocated slot id
    private int freeList = NIL; // head of recycled-slot list, linked via left[]
    private int modCount;

    /*
     * Out-parameters for the recursive insert/delete helpers, signalling whether
     * the subtree just returned changed height. Single-threaded use only.
     */
    private boolean taller;             // insert(): subtree grew by one
    private boolean shorter;            // delete(): subtree shrank by one
    private boolean rebalanceShortened; // rebalance: rotation reduced height

    /** Creates a tree that orders elements by their natural ordering. */
    AVLTree() {
        this.comparator = null;
    }

    /**
     * Creates a tree that orders elements with the given comparator.
     *
     * @param comparator the ordering to use; must not be {@code null}
     */
    AVLTree(Comparator<? super T> comparator) {
        this.comparator = Objects.requireNonNull(comparator, "comparator");
    }

    // ---------------------------------------------------------------------
    // Slot allocation (free list + growable arrays)
    // ---------------------------------------------------------------------

    private int allocate(T element) {
        int id;
        if (freeList != NIL) {
            id = freeList;
            freeList = left[id];
        } else {
            if (highWater == value.length) {
                grow();
            }
            id = highWater++;
        }
        value[id] = element;
        left[id] = NIL;
        right[id] = NIL;
        balance[id] = 0;
        return id;
    }

    private void release(int id) {
        value[id] = null; // drop the element reference so it can be collected
        left[id] = freeList;
        freeList = id;
    }

    private void grow() {
        int newCapacity = value.length + (value.length >> 1) + 1;
        value = Arrays.copyOf(value, newCapacity);
        left = Arrays.copyOf(left, newCapacity);
        right = Arrays.copyOf(right, newCapacity);
        balance = Arrays.copyOf(balance, newCapacity);
    }

    @SuppressWarnings("unchecked")
    private T value(int id) {
        return (T) value[id];
    }

    // ---------------------------------------------------------------------
    // Set / Collection API
    // ---------------------------------------------------------------------

    /**
     * Inserts {@code element}, keeping the tree balanced.
     *
     * @param element the element to add; must not be {@code null}
     * @return {@code true} if the element was added, {@code false} if an equal
     *         element was already present
     */
    @Override
    public boolean add(T element) {
        Objects.requireNonNull(element, "value");
        int sizeBefore = size;
        root = insert(root, element);
        boolean changed = size != sizeBefore;
        if (changed) {
            modCount++;
        }
        return changed;
    }

    /**
     * Removes the element equal to {@code o}, keeping the tree balanced.
     *
     * @param o the element to remove; must not be {@code null}
     * @return {@code true} if an element was removed
     */
    @Override
    @SuppressWarnings("unchecked")
    public boolean remove(Object o) {
        Objects.requireNonNull(o, "value");
        int sizeBefore = size;
        root = delete(root, (T) o);
        boolean changed = size != sizeBefore;
        if (changed) {
            modCount++;
        }
        return changed;
    }

    /**
     * Returns whether an element equal to {@code o} is present.
     *
     * @param o the element to look for; must not be {@code null}
     */
    @Override
    @SuppressWarnings("unchecked")
    public boolean contains(Object o) {
        Objects.requireNonNull(o, "value");
        int node = root;
        while (node != NIL) {
            int cmp = compare((T) o, value(node));
            if (cmp < 0) {
                node = left[node];
            } else if (cmp > 0) {
                node = right[node];
            } else {
                return true;
            }
        }
        return false;
    }

    @Override
    public int size() {
        return size;
    }

    @Override
    public void clear() {
        if (size != 0) {
            modCount++;
        }
        Arrays.fill(value, 0, highWater, null);
        root = NIL;
        size = 0;
        highWater = 0;
        freeList = NIL;
    }

    /** Iterates over all elements in ascending order. */
    @Override
    public Iterator<T> iterator() {
        return new InOrderIterator(null, false, null, false);
    }

    // ---------------------------------------------------------------------
    // SortedSet API
    // ---------------------------------------------------------------------

    @Override
    public Comparator<? super T> comparator() {
        return comparator;
    }

    @Override
    public T first() {
        return min();
    }

    @Override
    public T last() {
        return max();
    }

    @Override
    public SortedSet<T> subSet(T fromInclusive, T toExclusive) {
        Objects.requireNonNull(fromInclusive, "fromElement");
        Objects.requireNonNull(toExclusive, "toElement");
        return new SubSet(fromInclusive, true, toExclusive, true);
    }

    @Override
    public SortedSet<T> headSet(T toExclusive) {
        Objects.requireNonNull(toExclusive, "toElement");
        return new SubSet(null, false, toExclusive, true);
    }

    @Override
    public SortedSet<T> tailSet(T fromInclusive) {
        Objects.requireNonNull(fromInclusive, "fromElement");
        return new SubSet(fromInclusive, true, null, false);
    }

    // ---------------------------------------------------------------------
    // Additional ordered queries
    // ---------------------------------------------------------------------

    /**
     * Returns the smallest element.
     *
     * @throws NoSuchElementException if the tree is empty
     */
    T min() {
        if (root == NIL) {
            throw new NoSuchElementException("empty tree");
        }
        return value(minNode(root));
    }

    /**
     * Returns the largest element.
     *
     * @throws NoSuchElementException if the tree is empty
     */
    T max() {
        if (root == NIL) {
            throw new NoSuchElementException("empty tree");
        }
        int node = root;
        while (right[node] != NIL) {
            node = right[node];
        }
        return value(node);
    }

    /**
     * Returns the largest element less than or equal to {@code element}, or an
     * empty {@link Optional} if no such element exists.
     *
     * @param element the reference element; must not be {@code null}
     */
    Optional<T> floor(T element) {
        Objects.requireNonNull(element, "value");
        int node = root;
        T best = null;
        while (node != NIL) {
            int cmp = compare(element, value(node));
            if (cmp == 0) {
                return Optional.of(value(node));
            } else if (cmp < 0) {
                node = left[node];
            } else {
                best = value(node);
                node = right[node];
            }
        }
        return Optional.ofNullable(best);
    }

    /**
     * Returns the smallest element greater than or equal to {@code element}, or
     * an empty {@link Optional} if no such element exists.
     *
     * @param element the reference element; must not be {@code null}
     */
    Optional<T> ceiling(T element) {
        Objects.requireNonNull(element, "value");
        int node = root;
        T best = null;
        while (node != NIL) {
            int cmp = compare(element, value(node));
            if (cmp == 0) {
                return Optional.of(value(node));
            } else if (cmp > 0) {
                node = right[node];
            } else {
                best = value(node);
                node = left[node];
            }
        }
        return Optional.ofNullable(best);
    }

    /**
     * Returns the height of the tree (0 for an empty tree), computed on the fly
     * in O(log n) by descending the taller side at each node, as told by the
     * stored balance factor.
     */
    int height() {
        int h = 0;
        int node = root;
        while (node != NIL) {
            h++;
            node = balance[node] >= 0 ? left[node] : right[node];
        }
        return h;
    }

    /** Returns the elements in ascending (sorted) order. */
    List<T> inOrder() {
        List<T> out = new ArrayList<>(size);
        inOrder(root, out);
        return out;
    }

    /** Returns the elements in pre-order (root, left subtree, right subtree). */
    List<T> preOrder() {
        List<T> out = new ArrayList<>(size);
        preOrder(root, out);
        return out;
    }

    /**
     * Verifies that every AVL invariant holds: binary-search ordering, that each
     * stored balance factor equals the true {@code height(left) - height(right)},
     * that every balance factor is within {@code [-1, +1]}, and {@link #size}.
     * Heights are recomputed from scratch here (O(n)); intended for tests and
     * debugging.
     *
     * @throws IllegalStateException if any invariant is violated
     */
    void validate() {
        validateCount = 0;
        validateHeight(root, null, null);
        if (validateCount != size) {
            throw new IllegalStateException(
                    "size mismatch: tracked " + size + " but counted " + validateCount);
        }
    }

    private int validateCount;

    // ---------------------------------------------------------------------
    // Insertion (incremental balance-factor maintenance)
    // ---------------------------------------------------------------------

    private int insert(int node, T element) {
        if (node == NIL) {
            size++;
            taller = true;
            return allocate(element);
        }

        int cmp = compare(element, value(node));
        if (cmp == 0) {
            taller = false;
            return node; // duplicate: no change
        }

        if (cmp < 0) {
            left[node] = insert(left[node], element);
            if (taller) {
                // Left subtree grew: bf = h(left) - h(right) increases by one.
                balance[node]++;
                if (balance[node] == 0) {
                    taller = false;        // filled a right-leaning gap; height unchanged
                } else if (balance[node] == 1) {
                    taller = true;         // now leans left; height grew
                } else {                   // balance[node] == 2: rebalance
                    node = rebalanceLeftHeavy(node);
                    taller = false;        // insertion rotations restore the old height
                }
            }
        } else {
            right[node] = insert(right[node], element);
            if (taller) {
                balance[node]--;
                if (balance[node] == 0) {
                    taller = false;
                } else if (balance[node] == -1) {
                    taller = true;
                } else {                   // balance[node] == -2: rebalance
                    node = rebalanceRightHeavy(node);
                    taller = false;
                }
            }
        }
        return node;
    }

    // ---------------------------------------------------------------------
    // Deletion (incremental balance-factor maintenance)
    // ---------------------------------------------------------------------

    private int delete(int node, T element) {
        if (node == NIL) {
            shorter = false;
            return NIL; // not found
        }

        int cmp = compare(element, value(node));
        if (cmp < 0) {
            left[node] = delete(left[node], element);
            if (shorter) {
                node = fixAfterLeftShrink(node);
            }
        } else if (cmp > 0) {
            right[node] = delete(right[node], element);
            if (shorter) {
                node = fixAfterRightShrink(node);
            }
        } else if (left[node] == NIL || right[node] == NIL) {
            // Zero or one child: splice the node out; the subtree shrinks.
            size--;
            shorter = true;
            int child = (left[node] != NIL) ? left[node] : right[node];
            release(node);
            return child;
        } else {
            // Two children: copy the in-order successor up, then delete it from
            // the right subtree (which shrinks if its height drops).
            int successor = minNode(right[node]);
            T successorValue = value(successor);
            value[node] = successorValue;
            right[node] = delete(right[node], successorValue);
            if (shorter) {
                node = fixAfterRightShrink(node);
            }
        }
        return node;
    }

    /** A left child shrank: drop bf by one and rebalance if it underflows. */
    private int fixAfterLeftShrink(int node) {
        balance[node]--;
        if (balance[node] == 0) {
            shorter = true;            // was left-leaning; now balanced and shorter
        } else if (balance[node] == -1) {
            shorter = false;           // now leans right but height unchanged
        } else {                       // balance[node] == -2: right-heavy violation
            node = rebalanceRightHeavy(node);
            shorter = rebalanceShortened;
        }
        return node;
    }

    /** A right child shrank: raise bf by one and rebalance if it overflows. */
    private int fixAfterRightShrink(int node) {
        balance[node]++;
        if (balance[node] == 0) {
            shorter = true;
        } else if (balance[node] == 1) {
            shorter = false;
        } else {                       // balance[node] == 2: left-heavy violation
            node = rebalanceLeftHeavy(node);
            shorter = rebalanceShortened;
        }
        return node;
    }

    // ---------------------------------------------------------------------
    // Rebalancing: rotations plus direct balance-factor recomputation
    // ---------------------------------------------------------------------

    /**
     * Repairs a node whose balance factor has reached +2 (left-heavy). The new
     * balance factors are derived from the children's, never from heights. Sets
     * {@link #rebalanceShortened} to whether the subtree's height dropped by one.
     */
    private int rebalanceLeftHeavy(int node) {
        int leftChild = left[node];
        if (balance[leftChild] >= 0) {
            // Left-Left. balance[leftChild] == +1 on insert; may be 0 on delete.
            boolean leftBalanced = balance[leftChild] == 0;
            rebalanceShortened = !leftBalanced;
            node = rotateRight(node);
            if (leftBalanced) {
                balance[node] = -1;        // new root (old left child)
                balance[right[node]] = 1;  // old node
            } else {
                balance[node] = 0;
                balance[right[node]] = 0;
            }
        } else {
            // Left-Right: rotate the left child left, then this node right.
            int pivotBf = balance[right[left[node]]];
            left[node] = rotateLeft(left[node]);
            node = rotateRight(node);
            applyDoubleRotationBalance(node, pivotBf);
            rebalanceShortened = true; // a double rotation always lowers the height
        }
        return node;
    }

    /** Mirror image of {@link #rebalanceLeftHeavy} for a balance factor of -2. */
    private int rebalanceRightHeavy(int node) {
        int rightChild = right[node];
        if (balance[rightChild] <= 0) {
            // Right-Right.
            boolean rightBalanced = balance[rightChild] == 0;
            rebalanceShortened = !rightBalanced;
            node = rotateLeft(node);
            if (rightBalanced) {
                balance[node] = 1;
                balance[left[node]] = -1;
            } else {
                balance[node] = 0;
                balance[left[node]] = 0;
            }
        } else {
            // Right-Left.
            int pivotBf = balance[left[right[node]]];
            right[node] = rotateRight(right[node]);
            node = rotateLeft(node);
            applyDoubleRotationBalance(node, pivotBf);
            rebalanceShortened = true;
        }
        return node;
    }

    /**
     * After a double rotation, {@code rootId} is the former grandchild pivot and
     * its two children are the other two rotated nodes. Their balance factors
     * depend only on the pivot's balance factor before the rotation.
     */
    private void applyDoubleRotationBalance(int rootId, int pivotBf) {
        if (pivotBf > 0) {
            balance[left[rootId]] = 0;
            balance[right[rootId]] = -1;
        } else if (pivotBf < 0) {
            balance[left[rootId]] = 1;
            balance[right[rootId]] = 0;
        } else {
            balance[left[rootId]] = 0;
            balance[right[rootId]] = 0;
        }
        balance[rootId] = 0;
    }

    /** Pure structural right rotation; balance factors are fixed up by callers. */
    private int rotateRight(int y) {
        int x = left[y];
        left[y] = right[x];
        right[x] = y;
        return x;
    }

    /** Pure structural left rotation; balance factors are fixed up by callers. */
    private int rotateLeft(int x) {
        int y = right[x];
        right[x] = left[y];
        left[y] = x;
        return y;
    }

    private int minNode(int node) {
        while (left[node] != NIL) {
            node = left[node];
        }
        return node;
    }

    // ---------------------------------------------------------------------
    // Traversals
    // ---------------------------------------------------------------------

    private void inOrder(int node, List<T> out) {
        if (node != NIL) {
            inOrder(left[node], out);
            out.add(value(node));
            inOrder(right[node], out);
        }
    }

    private void preOrder(int node, List<T> out) {
        if (node != NIL) {
            out.add(value(node));
            preOrder(left[node], out);
            preOrder(right[node], out);
        }
    }

    // ---------------------------------------------------------------------
    // Comparison and validation helpers
    // ---------------------------------------------------------------------

    @SuppressWarnings("unchecked")
    private int compare(T a, T b) {
        if (comparator != null) {
            return comparator.compare(a, b);
        }
        return ((Comparable<? super T>) a).compareTo(b);
    }

    /** Recomputes heights bottom-up, checking ordering and balance factors. */
    private int validateHeight(int node, T lowerExclusive, T upperExclusive) {
        if (node == NIL) {
            return 0;
        }
        T v = value(node);
        if (lowerExclusive != null && compare(v, lowerExclusive) <= 0) {
            throw new IllegalStateException("BST order violated at " + v);
        }
        if (upperExclusive != null && compare(v, upperExclusive) >= 0) {
            throw new IllegalStateException("BST order violated at " + v);
        }

        validateCount++;
        int leftHeight = validateHeight(left[node], lowerExclusive, v);
        int rightHeight = validateHeight(right[node], v, upperExclusive);

        int actualBf = leftHeight - rightHeight;
        if (balance[node] != actualBf) {
            throw new IllegalStateException("stale balance factor at " + v
                    + ": stored " + balance[node] + " but actual " + actualBf);
        }
        if (Math.abs(actualBf) > 1) {
            throw new IllegalStateException("unbalanced at " + v
                    + " (balance factor " + actualBf + ")");
        }
        return 1 + Math.max(leftHeight, rightHeight);
    }

    // ---------------------------------------------------------------------
    // Iterator
    // ---------------------------------------------------------------------

    /**
     * Lazy, fail-fast in-order iterator. An explicit {@code int} stack holds the
     * path of not-yet-visited ancestor ids, so iteration uses O(h) memory and no
     * boxing. An optional inclusive lower bound and exclusive upper bound
     * restrict it to a range, which is how the {@link SubSet} views iterate.
     */
    private final class InOrderIterator implements Iterator<T> {
        private int[] stack = new int[8];
        private int top; // number of ids on the stack
        private final T hi;
        private final boolean hasHi;
        private T lastReturned;
        private boolean canRemove;
        private int expectedModCount = modCount;

        InOrderIterator(T lo, boolean hasLo, T hi, boolean hasHi) {
            this.hi = hi;
            this.hasHi = hasHi;
            int node = root;
            while (node != NIL) {
                if (!hasLo || compare(value(node), lo) >= 0) {
                    push(node);
                    node = left[node];
                } else {
                    node = right[node];
                }
            }
        }

        private void push(int id) {
            if (top == stack.length) {
                stack = Arrays.copyOf(stack, top * 2);
            }
            stack[top++] = id;
        }

        @Override
        public boolean hasNext() {
            checkForComodification();
            return top > 0 && (!hasHi || compare(value(stack[top - 1]), hi) < 0);
        }

        @Override
        public T next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            int node = stack[--top];
            lastReturned = value(node);
            canRemove = true;
            for (int n = right[node]; n != NIL; n = left[n]) {
                push(n);
            }
            return lastReturned;
        }

        @Override
        public void remove() {
            if (!canRemove) {
                throw new IllegalStateException();
            }
            checkForComodification();
            AVLTree.this.remove(lastReturned);
            expectedModCount = modCount;
            // Rebalancing may have rearranged nodes (and recycled slots), so
            // rebuild the stack by seeking to the successor of the removed value.
            top = 0;
            int node = root;
            while (node != NIL) {
                if (compare(lastReturned, value(node)) < 0) {
                    push(node);
                    node = left[node];
                } else {
                    node = right[node];
                }
            }
            canRemove = false;
            lastReturned = null;
        }

        private void checkForComodification() {
            if (modCount != expectedModCount) {
                throw new ConcurrentModificationException();
            }
        }
    }

    // ---------------------------------------------------------------------
    // Range views (subSet / headSet / tailSet)
    // ---------------------------------------------------------------------

    /**
     * A live view of the elements in {@code [lo, hi)}, backed by the enclosing
     * tree. All mutations and queries delegate to the backing tree after a range
     * check, so changes are visible in both directions.
     */
    private final class SubSet extends AbstractSet<T> implements SortedSet<T> {
        private final T lo;
        private final boolean hasLo;
        private final T hi;
        private final boolean hasHi;

        SubSet(T lo, boolean hasLo, T hi, boolean hasHi) {
            if (hasLo && hasHi && compare(lo, hi) > 0) {
                throw new IllegalArgumentException("fromElement > toElement");
            }
            this.lo = lo;
            this.hasLo = hasLo;
            this.hi = hi;
            this.hasHi = hasHi;
        }

        private boolean tooLow(T e) {
            return hasLo && compare(e, lo) < 0;
        }

        private boolean tooHigh(T e) {
            return hasHi && compare(e, hi) >= 0;
        }

        private boolean inRange(T e) {
            return !tooLow(e) && !tooHigh(e);
        }

        /** Whether {@code e} is acceptable as an exclusive upper bound argument. */
        private boolean inRangeAsUpperBound(T e) {
            return !tooLow(e) && (!hasHi || compare(e, hi) <= 0);
        }

        @Override
        public Comparator<? super T> comparator() {
            return AVLTree.this.comparator();
        }

        @Override
        @SuppressWarnings("unchecked")
        public boolean contains(Object o) {
            Objects.requireNonNull(o, "value");
            return inRange((T) o) && AVLTree.this.contains(o);
        }

        @Override
        public boolean add(T e) {
            Objects.requireNonNull(e, "value");
            if (!inRange(e)) {
                throw new IllegalArgumentException("element out of range: " + e);
            }
            return AVLTree.this.add(e);
        }

        @Override
        @SuppressWarnings("unchecked")
        public boolean remove(Object o) {
            Objects.requireNonNull(o, "value");
            return inRange((T) o) && AVLTree.this.remove(o);
        }

        @Override
        public Iterator<T> iterator() {
            return new InOrderIterator(lo, hasLo, hi, hasHi);
        }

        @Override
        public int size() {
            int count = 0;
            for (Iterator<T> it = iterator(); it.hasNext(); it.next()) {
                count++;
            }
            return count;
        }

        @Override
        public boolean isEmpty() {
            return !iterator().hasNext();
        }

        @Override
        public T first() {
            Iterator<T> it = iterator();
            if (!it.hasNext()) {
                throw new NoSuchElementException();
            }
            return it.next();
        }

        @Override
        public T last() {
            int node = root;
            T best = null;
            while (node != NIL) {
                T v = value(node);
                if (tooHigh(v)) {
                    node = left[node];
                } else {
                    if (!tooLow(v)) {
                        best = v;
                    }
                    node = right[node];
                }
            }
            if (best == null) {
                throw new NoSuchElementException();
            }
            return best;
        }

        @Override
        public SortedSet<T> subSet(T from, T to) {
            Objects.requireNonNull(from, "fromElement");
            Objects.requireNonNull(to, "toElement");
            if (!inRange(from)) {
                throw new IllegalArgumentException("fromElement out of range: " + from);
            }
            if (!inRangeAsUpperBound(to)) {
                throw new IllegalArgumentException("toElement out of range: " + to);
            }
            return new SubSet(from, true, to, true);
        }

        @Override
        public SortedSet<T> headSet(T to) {
            Objects.requireNonNull(to, "toElement");
            if (!inRangeAsUpperBound(to)) {
                throw new IllegalArgumentException("toElement out of range: " + to);
            }
            return new SubSet(lo, hasLo, to, true);
        }

        @Override
        public SortedSet<T> tailSet(T from) {
            Objects.requireNonNull(from, "fromElement");
            if (!inRange(from)) {
                throw new IllegalArgumentException("fromElement out of range: " + from);
            }
            return new SubSet(from, true, hi, hasHi);
        }
    }
}

/**
 * Demonstrates and self-tests the {@link AVLTree} API, including its
 * {@link SortedSet} conformance and the array-backed balance-factor logic. Every
 * operation is checked with assertions, the tree's invariants are re-validated
 * after each mutation, and behaviour is cross-checked against {@link TreeSet}
 * (including a long randomized differential test that also stresses slot
 * allocation and free-list reuse), so a clean run is evidence of correctness
 * rather than something to eyeball.
 */
class Main {
    public static void main(String[] args) {
        // ---- Original demo, plus invariant checks ----
        AVLTree<Integer> tree = new AVLTree<>();
        for (int key : new int[] {10, 20, 30, 40, 50, 25}) {
            tree.add(key);
        }
        tree.validate();

        System.out.println("pre-order : " + tree.preOrder());
        System.out.println("in-order  : " + tree.inOrder());

        check(tree.preOrder().equals(List.of(30, 20, 10, 25, 40, 50)), "pre-order");
        check(tree.inOrder().equals(List.of(10, 20, 25, 30, 40, 50)), "sorted order");
        check(tree.size() == 6, "size");
        check(tree.height() == 3, "height");
        check(tree.contains(25) && !tree.contains(99), "contains");
        check(tree.min() == 10 && tree.max() == 50, "min/max");
        check(tree.floor(26).equals(Optional.of(25)), "floor");
        check(tree.ceiling(26).equals(Optional.of(30)), "ceiling");
        check(!tree.add(25), "duplicate add reports no change");
        check(tree.remove(30) && !tree.remove(30), "remove reports change once");
        tree.validate();
        check(tree.inOrder().equals(List.of(10, 20, 25, 40, 50)), "order after remove");

        // ---- SortedSet conformance ----
        AVLTree<Integer> set = new AVLTree<>();
        for (int v : new int[] {5, 3, 8, 1, 4, 7, 9, 2, 6}) {
            set.add(v);
        }
        check(set.comparator() == null, "natural ordering reports null comparator");
        check(set.first() == 1 && set.last() == 9, "first/last");

        SortedSet<Integer> model = new TreeSet<>(set);
        check(set.equals(model) && model.equals(set), "equals(TreeSet)");
        check(set.hashCode() == model.hashCode(), "hashCode matches TreeSet");

        check(toList(set.subSet(3, 7)).equals(List.of(3, 4, 5, 6)), "subSet");
        check(toList(set.headSet(4)).equals(List.of(1, 2, 3)), "headSet");
        check(toList(set.tailSet(7)).equals(List.of(7, 8, 9)), "tailSet");
        check(set.subSet(3, 7).first() == 3 && set.subSet(3, 7).last() == 6, "view first/last");

        set.subSet(3, 7).clear();
        set.validate();
        check(set.inOrder().equals(List.of(1, 2, 7, 8, 9)), "subSet.clear writes through");

        SortedSet<Integer> tail = set.tailSet(5);
        set.add(6);
        check(toList(tail).equals(List.of(6, 7, 8, 9)), "view reflects backing changes");

        check(throwsIAE(() -> set.subSet(1, 3).add(9)), "out-of-range add rejected");

        Iterator<Integer> it = set.iterator();
        while (it.hasNext()) {
            if (it.next() == 8) {
                it.remove();
            }
        }
        set.validate();
        check(!set.contains(8), "iterator.remove writes through");

        AVLTree<Integer> failFast = new AVLTree<>();
        failFast.addAll(List.of(1, 2, 3));
        check(throwsCME(() -> {
            for (Integer x : failFast) {
                failFast.add(100 + x);
            }
        }), "fail-fast iterator");

        check(set.containsAll(List.of(1, 2, 6)), "containsAll");
        set.removeAll(List.of(1, 2));
        set.validate();
        check(set.inOrder().equals(List.of(6, 7, 9)), "removeAll");
        set.retainAll(List.of(7, 9, 99));
        set.validate();
        check(set.inOrder().equals(List.of(7, 9)), "retainAll");
        check(set.addAll(List.of(7, 8, 9, 10)), "addAll reports change");
        check(set.inOrder().equals(List.of(7, 8, 9, 10)), "addAll");

        SortedSet<String> byLength = new AVLTree<>(
                Comparator.comparingInt(String::length).thenComparing(Comparator.naturalOrder()));
        byLength.add("bbb");
        byLength.add("a");
        byLength.add("cc");
        byLength.add("dd");
        check(toList(byLength).equals(List.of("a", "cc", "dd", "bbb")), "custom comparator order");
        check(byLength.comparator() != null, "comparator() reports the supplied comparator");

        // ---- Balancing + growth stress test ----
        AVLTree<Integer> big = new AVLTree<>();
        for (int i = 1; i <= 1000; i++) {
            big.add(i);
        }
        big.validate();
        check(big.height() <= 11, "balanced height for 1000 ascending inserts");
        for (int i = 1; i <= 1000; i += 2) {
            big.remove(i);
        }
        big.validate();
        check(big.size() == 500, "size after bulk removal");
        big.clear();
        check(big.isEmpty() && big.height() == 0, "clear empties the tree");

        // ---- Randomized differential test against TreeSet ----
        // Exercises every insertion/deletion rotation case plus array growth and
        // free-list slot reuse, with invariants re-checked throughout.
        Random rnd = new Random(20260620L);
        AVLTree<Integer> avl = new AVLTree<>();
        TreeSet<Integer> ref = new TreeSet<>();
        for (int step = 0; step < 50_000; step++) {
            int key = rnd.nextInt(600);
            if (rnd.nextBoolean()) {
                check(avl.add(key) == ref.add(key), "randomized add agrees with TreeSet");
            } else {
                check(avl.remove(key) == ref.remove(key), "randomized remove agrees with TreeSet");
            }
            if (step % 250 == 0) {
                avl.validate();
                check(avl.inOrder().equals(new ArrayList<>(ref)), "randomized contents match TreeSet");
            }
        }
        avl.validate();
        check(avl.inOrder().equals(new ArrayList<>(ref)), "final contents match TreeSet");
        check(avl.size() == ref.size(), "final size matches TreeSet");

        System.out.println("all checks passed (including 50,000 randomized ops vs TreeSet)");
    }

    private static <E> List<E> toList(Iterable<E> iterable) {
        List<E> out = new ArrayList<>();
        for (E e : iterable) {
            out.add(e);
        }
        return out;
    }

    private static boolean throwsIAE(Runnable r) {
        try {
            r.run();
            return false;
        } catch (IllegalArgumentException expected) {
            return true;
        }
    }

    private static boolean throwsCME(Runnable r) {
        try {
            r.run();
            return false;
        } catch (ConcurrentModificationException expected) {
            return true;
        }
    }

    private static void check(boolean condition, String what) {
        if (!condition) {
            throw new AssertionError("check failed: " + what);
        }
    }
}

